from pathlib import Path
import json,csv
R=Path(__file__).resolve().parents[1]
def explanations():
 d=json.loads((R/'data/diagnosticos/explicaciones_cpu.json').read_text())
 t='# Control descriptivo de explicaciones CICO\n\n'+d['alcance']+'\n\n## Método y procedencia\n\n'+d['metodo']+'\n\nModelo ONNX SHA-256: `'+d['modelo_sha256']+'`. Se conserva sin cambios. Seis recortes públicos con hashes en el archivo de resultados. Código reproducible: `tools/evaluar_explicaciones_cpu.py`; salida `data/diagnosticos/explicaciones_cpu.json`. Solo CPU.\n\n## Resultados por caso\n\nAUC es el área trapezoidal bajo la puntuación de la clase originalmente elegida frente a la fracción de bloques modificados; no es ROC-AUC. En eliminación, menor AUC es favorable; en inserción, mayor AUC es favorable. El control es la media de diez órdenes aleatorios fijos.\n\n| Caso | Δ AUC eliminación (mapa − azar) | Δ AUC inserción (mapa − azar) | Correlación del mapa tras rotación y alineación |\n|---|---:|---:|---:|\n'
 for x in d['casos']:t+=f"| {x['caso']} | {x['auc_eliminacion']-x['auc_eliminacion_aleatoria']:.6f} | {x['auc_insercion']-x['auc_insercion_aleatoria']:.6f} | {x['correlacion_mapa_rotado']:.8f} |\n"
 t+='\n## Interpretación y límite\n\nEn estos seis ejemplos, el orden del mapa reduce más rápidamente la puntuación al eliminar regiones y la recupera más rápidamente al insertarlas que el control aleatorio medio. La estabilidad ante una rotación de 90° es coherente con la simetría D4 del diseño. No se evaluó estabilidad frente a tinción, ruido o cambio de dominio.\n\nLas imágenes se seleccionaron para demostración y pertenecen a validación. La intervención y el mapa utilizan el mismo relleno, por lo que existe afinidad metodológica entre explicación y evaluación. No hay intervalos poblacionales ni prueba confirmatoria. El análisis no valida explicaciones clínicas y no corrige los 48 mapas constantes de Inception en E2. Falta un conjunto independiente y representativo, otros rellenos/perturbaciones y evaluar cada modelo principal.\n\n[Explorar las curvas en NuCLEA](https://nucls-entregable3.onrender.com/calidad-explicaciones).\n'
 return t

def power():
 d=json.loads((R/'data/diagnosticos/planificacion_potencia.json').read_text());t='# Planificación: sensibilidad a efecto y variabilidad\n\n'+d['alcance']+'\n\n## Fórmula y supuestos\n\n`'+d['formula']+'`. Se usa desviación de diferencias entre semillas, no dispersión de recortes como si fueran pacientes independientes. Alfa familiar 0,05; tres contrastes; objetivo individual 0,90. No demuestra potencia conjunta 0,90 ni satisface por sí solo la sección 8 de E3.\n\n| Variante | DE de diferencias | MDE aproximado con n=10 | Δ=0,01: n | Δ=0,02: n | Δ=0,03: n | Δ=0,05: n |\n|---|---:|---:|---:|---:|---:|---:|\n'
 for x in d['filas']:t+=f"| {x['variante']} | {x['sd_diferencias']:.5f} | {x['mde90_n10']:.5f} | "+' | '.join(str(s['n_con_piso_guia']) for s in x['escenarios'])+' |\n'
 t+='\nEl número mostrado incorpora el piso de diez semillas de la guía. No es una orden de ejecutar esas corridas: falta fijar el efecto mínimo relevante con justificación externa, la familia completa, la unidad independiente y simular las pruebas finales con corrección múltiple. El mínimo de diez semillas no asegura potencia suficiente.\n\n## Condiciones antes de correr el benchmark final\n\n1. Definir las preguntas, efectos mínimos relevantes, comparadores y controles sin elegirlos por el resultado favorable.\n2. Auditar particiones y tres datasets externos; no reutilizar la reserva histórica como prueba nueva.\n3. Justificar pruebas admisibles y su dependencia; no contar tres pruebas correlacionadas como tres replicaciones independientes.\n4. Estimar potencia individual y conjunta con el diseño y corrección finales; congelar protocolo y hashes antes de nuevas corridas.\n5. Conservar los análisis exploratorios actuales como tales, sin declararlos preregistrados retrospectivamente.\n\nCódigo: `tools/planificar_potencia.py`. Datos compartidos con NuCLEA: `data/diagnosticos/planificacion_potencia.json`.\n'
 t+='\n## E2: potencia y MDE históricos ya disponibles\n\nEl archivo histórico `data/proyecto/contrastes22.csv` contiene contrastes de las tres bases sobre 22 semillas. Se integra aquí sin recalcular ni modificar sus resultados. No corresponde a las 65 evaluaciones de reserva ni a PCam.\n\n| Contraste histórico | n | Δ medio | MDE80 familia 3 | MDE80 familia 10 | Potencia histórica Δ=0,02 / familia 10 | R histórico propuesto |\n|---|---:|---:|---:|---:|---:|---:|\n'
 for row in csv.DictReader((R/'data/proyecto/contrastes22.csv').open()):
  t+=f"| {row['comparacion']} | {row['n']} | {float(row['diferencia']):.5f} | {float(row['MDE80_familia3']):.5f} | {float(row['MDE80_familia10']):.5f} | {float(row['potencia_delta002_familia10']):.3f} | {row['R_delta002_familia10']} |\n"
 t+='\nEstos valores son cálculos históricos bajo sus supuestos y no justifican automáticamente las cinco semillas del benchmark de reserva. Falta cotejar el método original y justificar la familia y el efecto mínimo relevante; no se ordena repetir ni ampliar experimentos por esta tabla.\n'

 return t
if __name__=='__main__':
 (R/'book/22_calidad_explicaciones.md').write_text(explanations())
 (R/'book/23_planificacion_potencia.md').write_text(power())
